	for _, n := range out.WorkflowStates.Nodes {
		if strings.EqualFold(n.Name, wantName) {
			return n.ID, nil
		}
	}
	wantType := stateLinearType(target)
	for _, n := range out.WorkflowStates.Nodes {
		if n.Type == wantType {
