func stateDisplayName(s State) string {
	switch s {
	case StateTodo:
		return "Todo"
	case StateInProgress:
		return "In Progress"
	case StateInReview:
		return "In Review"
	case StateDone:
		return "Done"
	case StateUnknown:
		return ""
	default:
		return ""
	}
}

// stateLinearType is the Linear workflow-state type a State maps onto.
func stateLinearType(s State) string {
	switch s {
	case StateTodo:
		return "unstarted"
	case StateInProgress, StateInReview:
		return "started"
	case StateDone:
		return "completed"
	case StateUnknown:
		return ""
	default:
		return ""
	}
}

