		fmt.Fprintf(&b, "Work on ticket %s: %s\n\n", link.ID, task.Title)
		if body := strings.TrimSpace(task.Intent); body != "" {
			b.WriteString("Description:\n")
			b.WriteString(body)
			b.WriteString("\n\n")
		}
		if acc := strings.TrimSpace(task.Acceptance); acc != "" {
			b.WriteString("Acceptance criteria:\n")
			b.WriteString(acc)
			b.WriteString("\n\n")
		}
	} else {
		fmt.Fprintf(&b, "Work on ticket %s (%s).\n\n", link.ID, link.Platform)
	}
	b.WriteString("Implement the change on the current branch, following the conventions ")
	b.WriteString("already present in this codebase. When you are done, make sure the work ")
	b.WriteString("matches what the ticket asked for.\n")
	return b.String()
}

