func runStart(ctx context.Context, out io.Writer, deps Deps, id, agentName string, force bool) error {
	if deps.LaunchFix == nil {
		return errors.New("ticket start is unavailable: no agent launcher configured")
	}

	link, branch, err := linkCurrentBranch(ctx, id, force)
	if err != nil {
		return err
	}

	if agentName == "" {
		agentName = defaultStartAgent
	}

	// Fetch the ticket so the prompt carries its content. Best-effort: a fetch
	// failure must not block launching the agent.
	var task *Task
	if fetched, ferr := fetchTaskForStart(ctx, link); ferr == nil {
		task = fetched
	}

	fmt.Fprintf(out, "✓ Linked %s to branch %q. Launching %s …\n", link.ID, branch, agentName)
	return deps.LaunchFix(ctx, agentName, composeStartPrompt(link, task))
}

// fetchTaskForStart resolves the linked ticket via the active provider,
// returning a nil task (and the error) when it cannot be fetched.
func fetchTaskForStart(ctx context.Context, link Link) (*Task, error) {
	prov, err := activeProvider(ctx)
	if err != nil {
		return nil, err
	}
	task, err := prov.Fetch(ctx, link.ID)
	if err != nil {
		return nil, fmt.Errorf("fetch ticket %s: %w", link.ID, err)
	}
	return &task, nil
}

// composeStartPrompt builds the agent prompt for a start run. When the ticket
// was fetched it embeds the title, description, acceptance, discussion, and
// URL; otherwise it references the ticket by ID so the agent can look it up.
func composeStartPrompt(link Link, task *Task) string {
	var b strings.Builder
	if task == nil || task.Title == "" {
		fmt.Fprintf(&b, "Work on ticket %s (%s).\n\n", link.ID, link.Platform)
		b.WriteString(startInstructions)
		return b.String()
	}

	fmt.Fprintf(&b, "Work on ticket %s: %s\n\n", link.ID, task.Title)
	if body := strings.TrimSpace(task.Intent); body != "" {
		b.WriteString("Description:\n")
		b.WriteString(body)
		b.WriteString("\n\n")
	}
	if acc := strings.TrimSpace(task.Acceptance); acc != "" {
		b.WriteString("Acceptance criteria:\n")
		b.WriteString(acc)
		b.WriteString("\n\n")
	}
	if len(task.Comments) > 0 {
		b.WriteString("Discussion:\n")
		for _, c := range task.Comments {
			author := c.Author
			if author == "" {
				author = "unknown"
			}
			fmt.Fprintf(&b, "- %s: %s\n", author, strings.TrimSpace(c.Body))
		}
		b.WriteString("\n")
	}
	if task.URL != "" {
		fmt.Fprintf(&b, "Ticket: %s\n\n", task.URL)
	}
	b.WriteString(startInstructions)
	return b.String()
}

// startInstructions is the closing guidance appended to every start prompt.
const startInstructions = "Implement the change on the current branch, following the conventions " +
	"already present in this codebase. When you are done, make sure the work " +
	"matches what the ticket asked for.\n"

