	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, nil
	}
	changes := diffSnapshot(link.Snapshot, task)
	link.Snapshot = snapshotOf(task)
	if err := store.set(branch, link); err != nil {
		return nil, err
	}
	return changes, nil
}

